import json, pathlib

SCRATCH = pathlib.Path("/Users/joker/.gemini/antigravity-cli/brain/85d95df5-1966-4e95-bfea-59213d336305/scratch")
d = json.loads((SCRATCH / "identity_dates_01_output.json").read_text())

KEEP_CR_KEYS = {
    "DOI", "type", "title", "container-title", "short-container-title",
    "publisher", "volume", "issue", "page", "article-number",
    "published", "published-online", "published-print", "issued",
    "created", "deposited", "indexed", "event", "URL", "relation",
    "alternative-id", "author"
}

for s in d["sources"]:
    if s["source_class"] == "crossref":
        mf = {k: v for k, v in s["metadata_fields"].items() if k in KEEP_CR_KEYS}
        for dk in ("created", "deposited", "indexed"):
            if dk in mf and isinstance(mf[dk], dict):
                mf[dk] = {k: mf[dk][k] for k in ("date-parts", "date-time") if k in mf[dk]}
        s["metadata_fields"] = mf

# Also check word count of ALL excerpts (even local) just to be super tidy
for s in d["sources"]:
    wc = len(s["excerpt"].split())
    if s["source_class"] != "supplied_full_text":
        assert wc <= 25, f"{s['source_id']} wc={wc}"

compact = json.dumps(d, separators=(",", ":"), ensure_ascii=False)
(SCRATCH / "identity_dates_01_compact.json").write_text(compact)
print("Compact length:", len(compact))
PY

